import { type SearchConfig, type EntitySelectorRequestConfig } from './types/types';

export const EntityId = 'im-recent-v2';
const ContextId = 'IM_CHAT_SEARCH';
const SearchDialogId = 'im-chat-search';

export const getSearchConfig = (searchConfig: SearchConfig): EntitySelectorRequestConfig => {
	const {
		entityId = EntityId,
		contextId = ContextId,
		searchDialogId = SearchDialogId,
		// Fields of the ui.EntitySelector entity itself (e.g. fillRecentItems) are lifted onto the
		// entity; everything else goes to entity.options as provider options.
		entityConfig = {},
		...entityOptions
	} = searchConfig;

	const entity = {
		id: entityId,
		dynamicLoad: true,
		dynamicSearch: true,
		...entityConfig,
		options: entityOptions,
	};

	return {
		dialog: {
			entities: [
				entity,
			],
			preselectedItems: [],
			clearUnavailableItems: false,
			context: contextId,
			id: searchDialogId,
		},
	};
};
